import java.util.function.LongSupplier;

public class Solution {
    /** Conteúdo do arquivo cpu.max de um cgroup v2: "quota período" em microssegundos, ou "max período". */
    static final class CpuMax {
        static final long PERIODO_PADRAO_US = 100_000;
        static final long PERIODO_MIN_US = 1_000;
        static final long PERIODO_MAX_US = 1_000_000;
        static final long QUOTA_MIN_US = 1_000;

        private final long quotaUs; // -1 representa "max"
        private final long periodoUs;

        private CpuMax(long quotaUs, long periodoUs) {
            this.quotaUs = quotaUs;
            this.periodoUs = periodoUs;
        }

        static CpuMax parse(String linha) {
            if (linha == null) throw new IllegalArgumentException("linha nula");
            String texto = linha.trim();
            if (texto.isEmpty()) throw new IllegalArgumentException("linha vazia");
            String[] partes = texto.split("\\s+");
            if (partes.length > 2) throw new IllegalArgumentException("campos demais: " + linha);
            long periodo = partes.length == 2 ? numero(partes[1]) : PERIODO_PADRAO_US;
            if (periodo < PERIODO_MIN_US || periodo > PERIODO_MAX_US) {
                throw new IllegalArgumentException("período fora de 1000..1000000: " + periodo);
            }
            if (partes[0].equals("max")) return new CpuMax(-1, periodo);
            long quota = numero(partes[0]);
            if (quota < QUOTA_MIN_US) throw new IllegalArgumentException("quota abaixo de 1000: " + quota);
            return new CpuMax(quota, periodo);
        }

        private static long numero(String s) {
            if (!s.matches("\\d{1,15}")) throw new IllegalArgumentException("número inválido: " + s);
            return Long.parseLong(s);
        }

        boolean ilimitado() { return quotaUs < 0; }

        long quotaUs() { return quotaUs; }

        long periodoUs() { return periodoUs; }

        /** Quantas CPUs o grupo pode usar em média (infinito quando ilimitado). */
        double cpus() { return ilimitado() ? Double.POSITIVE_INFINITY : (double) quotaUs / periodoUs; }

        @Override public String toString() { return (ilimitado() ? "max" : String.valueOf(quotaUs)) + " " + periodoUs; }
    }

    record Resultado(long paredeUs, long periodos, long periodosThrottled, long throttledUs) {}

    /**
     * Simula {@code threads} threads sempre prontas para rodar até gastarem {@code trabalhoUs} de CPU no total,
     * sob o limite {@code max}. O grupo consome CPU a {@code threads} µs por µs de parede, até a quota do período.
     */
    static Resultado simular(CpuMax max, long trabalhoUs, int threads) {
        if (max == null) throw new IllegalArgumentException("max nulo");
        if (trabalhoUs < 0) throw new IllegalArgumentException("trabalho negativo");
        if (threads < 1) throw new IllegalArgumentException("threads < 1");
        long periodo = max.periodoUs();
        long capacidade = threads * periodo; // o que o grupo gastaria se ninguém o segurasse
        long permitido = max.ilimitado() ? capacidade : Math.min(max.quotaUs(), capacidade);
        boolean limita = permitido < capacidade;

        long restante = trabalhoUs;
        long parede = 0;
        long periodos = 0;
        long estrangulados = 0;
        long tempoEstrangulado = 0;
        while (restante > 0) {
            periodos++;
            long gasto = Math.min(restante, permitido);
            restante -= gasto;
            long rodando = (gasto + threads - 1) / threads; // µs de parede com as threads em execução
            if (restante > 0) {
                parede += periodo;
                if (limita) {
                    estrangulados++;
                    tempoEstrangulado += periodo - rodando;
                }
            } else {
                parede += rodando;
            }
        }
        return new Resultado(parede, periodos, estrangulados, tempoEstrangulado);
    }

    /** Contabilidade de quota de um grupo, com relógio injetado (µs). Os períodos são contados a partir do tempo 0 do relógio. */
    static final class CotaDeCpu {
        private final CpuMax max;
        private final LongSupplier relogioUs;
        private long periodoCorrente = -1;
        private long usado = 0;
        private long ultimoEstrangulado = -1;
        private long estrangulados = 0;

        CotaDeCpu(CpuMax max, LongSupplier relogioUs) {
            if (max == null || relogioUs == null) throw new IllegalArgumentException("argumento nulo");
            this.max = max;
            this.relogioUs = relogioUs;
        }

        /**
         * Pede para gastar {@code cpuUs} de CPU agora. Devolve 0 se coube na quota do período atual (e debita);
         * senão, devolve quantos µs faltam para o próximo período e não debita nada.
         */
        long consumir(long cpuUs) {
            if (cpuUs < 0) throw new IllegalArgumentException("cpuUs negativo");
            if (!max.ilimitado() && cpuUs > max.quotaUs()) throw new IllegalArgumentException("o pedido nunca cabe na quota");
            long agora = relogioUs.getAsLong();
            long periodo = agora / max.periodoUs();
            if (periodo != periodoCorrente) {
                periodoCorrente = periodo;
                usado = 0;
            }
            if (max.ilimitado() || usado + cpuUs <= max.quotaUs()) {
                usado += cpuUs;
                return 0;
            }
            if (ultimoEstrangulado != periodo) {
                ultimoEstrangulado = periodo;
                estrangulados++;
            }
            return (periodo + 1) * max.periodoUs() - agora;
        }

        long usadoNoPeriodo() { return usado; }

        /** Quantos períodos tiveram ao menos um pedido recusado (o nr_throttled do cpu.stat). */
        long periodosEstrangulados() { return estrangulados; }
    }
}

