import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import java.util.function.LongSupplier;

class SolutionTest {
    static final class Relogio implements LongSupplier {
        long agora = 0;
        @Override public long getAsLong() { return agora; }
        Relogio em(long t) { agora = t; return this; }
    }

    static Solution.CpuMax cpu(String linha) { return Solution.CpuMax.parse(linha); }

    // ---------- CpuMax ----------

    @Test void leQuotaEPeriodo() {
        Solution.CpuMax m = cpu("50000 100000");
        assertFalse(m.ilimitado());
        assertEquals(50_000, m.quotaUs());
        assertEquals(100_000, m.periodoUs());
        assertEquals(0.5, m.cpus(), 1e-9);
    }

    @Test void cpusPodeSerMaiorQueUm() {
        assertEquals(2.0, cpu("200000 100000").cpus(), 1e-9);
        assertEquals(1.5, cpu("75000 50000").cpus(), 1e-9);
    }

    @Test void maxSignificaSemLimite() {
        Solution.CpuMax m = cpu("max 100000");
        assertTrue(m.ilimitado());
        assertEquals(100_000, m.periodoUs());
        assertEquals(Double.POSITIVE_INFINITY, m.cpus());
    }

    @Test void soAQuotaMantemOPeriodoPadrao() {
        Solution.CpuMax m = cpu("25000");
        assertEquals(25_000, m.quotaUs());
        assertEquals(100_000, m.periodoUs());
        assertTrue(cpu("max").ilimitado());
        assertEquals(100_000, cpu("max").periodoUs());
    }

    @Test void toleraEspacosAoRedor() {
        Solution.CpuMax m = cpu("  50000   100000\n");
        assertEquals(50_000, m.quotaUs());
        assertEquals(100_000, m.periodoUs());
    }

    @Test void limitesDePeriodoEQuota() {
        assertEquals(1_000, cpu("1000 1000").quotaUs());
        assertEquals(1_000_000, cpu("500000 1000000").periodoUs());
        assertEquals(1_000, cpu("1000 1000").periodoUs());
    }

    @Test void rejeitaEntradasInvalidas() {
        String[] ruins = {
            "", "   ", "abc", "50000 100000 1", "-5000 100000", "+50000 100000", "50000 -1",
            "0 100000", "999 100000", "50000 999", "50000 1000001", "50000 0", "1.5 100000",
            "max max", "50000 max", "99999999999999999 100000"
        };
        for (String ruim : ruins) {
            assertThrows(IllegalArgumentException.class, () -> cpu(ruim), "deveria rejeitar: '" + ruim + "'");
        }
        assertThrows(IllegalArgumentException.class, () -> cpu(null));
    }

    // ---------- simular: tempo de parede e throttling ----------

    @Test void umaThreadComMeiaCpu() {
        Solution.Resultado r = Solution.simular(cpu("50000 100000"), 200_000, 1);
        assertEquals(4, r.periodos());
        assertEquals(3, r.periodosThrottled());
        assertEquals(350_000, r.paredeUs());
        assertEquals(150_000, r.throttledUs());
    }

    @Test void trabalhoCabeNaQuotaNaoEstrangula() {
        Solution.Resultado r = Solution.simular(cpu("50000 100000"), 30_000, 1);
        assertEquals(1, r.periodos());
        assertEquals(0, r.periodosThrottled());
        assertEquals(30_000, r.paredeUs());
        assertEquals(0, r.throttledUs());
    }

    @Test void trabalhoIgualAQuotaNaoEstrangula() {
        Solution.Resultado r = Solution.simular(cpu("50000 100000"), 50_000, 1);
        assertEquals(1, r.periodos());
        assertEquals(0, r.periodosThrottled());
        assertEquals(50_000, r.paredeUs());
    }

    @Test void trabalhoUmPoucoAcimaDaQuota() {
        Solution.Resultado r = Solution.simular(cpu("50000 100000"), 50_001, 1);
        assertEquals(2, r.periodos());
        assertEquals(1, r.periodosThrottled());
        assertEquals(100_001, r.paredeUs());
        assertEquals(50_000, r.throttledUs());
    }

    @Test void variasThreadsEsgotamAQuotaMaisRapido() {
        // 4 threads gastam 50 ms de CPU em 12,5 ms de parede e depois esperam o resto do período.
        Solution.Resultado r = Solution.simular(cpu("50000 100000"), 200_000, 4);
        assertEquals(4, r.periodos());
        assertEquals(3, r.periodosThrottled());
        assertEquals(3 * 100_000 + 12_500, r.paredeUs());
        assertEquals(3 * 87_500, r.throttledUs());
    }

    @Test void quotaAcimaDoQueAsThreadsConsomemNaoEstrangula() {
        // 2 threads gastam no máximo 200 ms por período; a quota de 300 ms nunca é atingida.
        Solution.Resultado r = Solution.simular(cpu("300000 100000"), 500_000, 2);
        assertEquals(3, r.periodos());
        assertEquals(0, r.periodosThrottled());
        assertEquals(250_000, r.paredeUs());
        assertEquals(0, r.throttledUs());
    }

    @Test void quotaDeDuasCpusComQuatroThreads() {
        Solution.Resultado r = Solution.simular(cpu("200000 100000"), 1_000_000, 4);
        assertEquals(5, r.periodos());
        assertEquals(4, r.periodosThrottled());
        assertEquals(4 * 100_000 + 50_000, r.paredeUs());
        assertEquals(4 * 50_000, r.throttledUs());
    }

    @Test void semLimiteOTempoEOTrabalhoDivididoPelasThreads() {
        Solution.Resultado r = Solution.simular(cpu("max 100000"), 1_000_000, 4);
        assertEquals(250_000, r.paredeUs());
        assertEquals(3, r.periodos());
        assertEquals(0, r.periodosThrottled());
        assertEquals(0, r.throttledUs());
    }

    @Test void arredondaOTempoDeParedeParaCima() {
        Solution.Resultado r = Solution.simular(cpu("max 100000"), 10, 3);
        assertEquals(4, r.paredeUs());
        assertEquals(1, r.periodos());
    }

    @Test void periodoMenorMudaAGranularidade() {
        // 0,5 CPU com período de 20 ms: 10 ms de quota por período.
        Solution.Resultado r = Solution.simular(cpu("10000 20000"), 35_000, 1);
        assertEquals(4, r.periodos());
        assertEquals(3, r.periodosThrottled());
        assertEquals(3 * 20_000 + 5_000, r.paredeUs());
        assertEquals(3 * 10_000, r.throttledUs());
    }

    @Test void semTrabalhoNaoHaNada() {
        Solution.Resultado r = Solution.simular(cpu("50000 100000"), 0, 2);
        assertEquals(0, r.paredeUs());
        assertEquals(0, r.periodos());
        assertEquals(0, r.periodosThrottled());
        assertEquals(0, r.throttledUs());
    }

    @Test void argumentosInvalidosDoSimulador() {
        assertThrows(IllegalArgumentException.class, () -> Solution.simular(cpu("50000 100000"), -1, 1));
        assertThrows(IllegalArgumentException.class, () -> Solution.simular(cpu("50000 100000"), 10, 0));
        assertThrows(IllegalArgumentException.class, () -> Solution.simular(null, 10, 1));
    }

    @Test void trabalhoGrandeTerminaRapido() {
        long inicio = System.nanoTime();
        Solution.Resultado r = Solution.simular(cpu("1000 100000"), 100_000_000L, 1);
        assertEquals(100_000, r.periodos());
        assertEquals(99_999, r.periodosThrottled());
        assertTrue((System.nanoTime() - inicio) / 1_000_000 < 3_000, "deveria levar bem menos de 3 s");
    }

    // ---------- CotaDeCpu com relógio injetado ----------

    @Test void pedidosQueCabemNaQuotaPassam() {
        Relogio rel = new Relogio();
        Solution.CotaDeCpu cota = new Solution.CotaDeCpu(cpu("50000 100000"), rel);
        assertEquals(0, cota.consumir(20_000));
        assertEquals(0, cota.consumir(30_000));
        assertEquals(50_000, cota.usadoNoPeriodo());
        assertEquals(0, cota.periodosEstrangulados());
    }

    @Test void pedidoQueEstouraEEsperaOProximoPeriodo() {
        Relogio rel = new Relogio();
        Solution.CotaDeCpu cota = new Solution.CotaDeCpu(cpu("50000 100000"), rel);
        assertEquals(0, cota.consumir(50_000));
        rel.em(10_000);
        assertEquals(90_000, cota.consumir(1));
        assertEquals(50_000, cota.usadoNoPeriodo());
        assertEquals(1, cota.periodosEstrangulados());
    }

    @Test void recusaNaoDebitaNada() {
        Relogio rel = new Relogio();
        Solution.CotaDeCpu cota = new Solution.CotaDeCpu(cpu("50000 100000"), rel);
        assertEquals(0, cota.consumir(40_000));
        assertEquals(100_000, cota.consumir(20_000));
        assertEquals(40_000, cota.usadoNoPeriodo());
        assertEquals(0, cota.consumir(10_000));
        assertEquals(50_000, cota.usadoNoPeriodo());
    }

    @Test void novoPeriodoZeraOUso() {
        Relogio rel = new Relogio();
        Solution.CotaDeCpu cota = new Solution.CotaDeCpu(cpu("50000 100000"), rel);
        assertEquals(0, cota.consumir(50_000));
        rel.em(100_000);
        assertEquals(0, cota.consumir(50_000));
        assertEquals(50_000, cota.usadoNoPeriodo());
        rel.em(250_000);
        assertEquals(0, cota.consumir(1_000));
        assertEquals(1_000, cota.usadoNoPeriodo());
    }

    @Test void esperaAteOInicioDoProximoPeriodoAlinhado() {
        Relogio rel = new Relogio().em(1_234_567);
        Solution.CotaDeCpu cota = new Solution.CotaDeCpu(cpu("10000 100000"), rel);
        assertEquals(0, cota.consumir(10_000));
        assertEquals(65_433, cota.consumir(5_000));
        rel.em(1_300_000);
        assertEquals(0, cota.consumir(5_000));
    }

    @Test void contaOPeriodoEstranguladoUmaVezSo() {
        Relogio rel = new Relogio();
        Solution.CotaDeCpu cota = new Solution.CotaDeCpu(cpu("50000 100000"), rel);
        cota.consumir(50_000);
        cota.consumir(1);
        rel.em(20_000);
        cota.consumir(1);
        assertEquals(1, cota.periodosEstrangulados());
        rel.em(100_000);
        assertEquals(0, cota.consumir(50_000));
        rel.em(150_000);
        assertTrue(cota.consumir(1) > 0);
        assertEquals(2, cota.periodosEstrangulados());
    }

    @Test void semLimiteNuncaEstrangula() {
        Relogio rel = new Relogio();
        Solution.CotaDeCpu cota = new Solution.CotaDeCpu(cpu("max 100000"), rel);
        assertEquals(0, cota.consumir(900_000_000L));
        assertEquals(0, cota.consumir(900_000_000L));
        assertEquals(0, cota.periodosEstrangulados());
    }

    @Test void pedidoMaiorQueAQuotaInteiraNuncaCabe() {
        Relogio rel = new Relogio();
        Solution.CotaDeCpu cota = new Solution.CotaDeCpu(cpu("50000 100000"), rel);
        assertThrows(IllegalArgumentException.class, () -> cota.consumir(50_001));
        assertThrows(IllegalArgumentException.class, () -> cota.consumir(-1));
        assertEquals(0, cota.consumir(0));
        assertEquals(0, cota.consumir(50_000));
    }

    @Test void construtorRejeitaNulos() {
        assertThrows(IllegalArgumentException.class, () -> new Solution.CotaDeCpu(null, () -> 0));
        assertThrows(IllegalArgumentException.class, () -> new Solution.CotaDeCpu(cpu("50000 100000"), null));
    }
}
